"use client";

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import {
  Users,
  MapPin,
  Flame,
  CheckCircle2,
  TrendingUp,
  Thermometer,
  Snowflake,
  Phone,
  Globe,
} from "lucide-react";
import { api } from "@/lib/api";
import type { DashboardStats } from "@geolead/types";

export default function DashboardPage() {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    api.getStats()
      .then((result) => { if (result.success) setStats(result.data); })
      .catch(console.error)
      .finally(() => setLoading(false));
  }, []);

  const statCards = stats
    ? [
      { title: "Total Leads", value: stats.totalLeads.toLocaleString(), icon: Users, description: `${stats.newThisWeek} new this week`, color: "text-blue-600" },
      { title: "With Phone", value: (stats.withPhone ?? 0).toLocaleString(), icon: Phone, description: `${stats.totalLeads > 0 ? Math.round(((stats.withPhone ?? 0) / stats.totalLeads) * 100) : 0}% of total`, color: "text-green-600" },
      { title: "With Website", value: (stats.withWebsite ?? 0).toLocaleString(), icon: Globe, description: `${stats.totalLeads > 0 ? Math.round(((stats.withWebsite ?? 0) / stats.totalLeads) * 100) : 0}% of total`, color: "text-blue-500" },
      { title: "Contacted", value: stats.contactedCount.toLocaleString(), icon: CheckCircle2, description: `${stats.contactRate}% contact rate`, color: "text-purple-600" },
    ]
    : [];

  const formatTimeAgo = (dateStr: string) => {
    const diff = Date.now() - new Date(dateStr).getTime();
    const mins = Math.floor(diff / 60000);
    if (mins < 60) return `${mins}m ago`;
    const hours = Math.floor(mins / 60);
    if (hours < 24) return `${hours}h ago`;
    return `${Math.floor(hours / 24)}d ago`;
  };

  if (loading) {
    return (
      <div className="flex flex-col gap-8 animate-in fade-in duration-500">
        <div className="flex flex-col gap-2">
          <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
          <p className="text-muted-foreground">Loading your data...</p>
        </div>
        <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
          {[1, 2, 3, 4].map((i) => (
            <Card key={i} className="animate-pulse">
              <CardHeader className="pb-2"><div className="h-4 w-24 bg-muted rounded" /></CardHeader>
              <CardContent><div className="h-8 w-16 bg-muted rounded" /></CardContent>
            </Card>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-8 animate-in fade-in duration-500">
      <div className="flex flex-col gap-2">
        <h1 className="text-3xl font-bold tracking-tight">Dashboard</h1>
        <p className="text-muted-foreground">Welcome back. Here&apos;s an overview of your lead generation progress.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        {statCards.map((stat) => {
          const Icon = stat.icon;
          return (
            <Card key={stat.title} className="hover:shadow-md transition-shadow">
              <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                <CardTitle className="text-sm font-medium">{stat.title}</CardTitle>
                <Icon className={`h-4 w-4 ${stat.color}`} />
              </CardHeader>
              <CardContent>
                <div className="text-2xl font-bold">{stat.value}</div>
                <p className="text-xs text-muted-foreground mt-1">{stat.description}</p>
              </CardContent>
            </Card>
          );
        })}
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-7">
        <Card className="col-span-4">
          <CardHeader><CardTitle>Quick Stats</CardTitle></CardHeader>
          <CardContent>
            <div className="grid grid-cols-3 gap-4">
              <div className="flex flex-col items-center p-4 bg-muted/40 rounded-lg">
                <Flame className="h-6 w-6 text-orange-500 mb-2" />
                <span className="text-2xl font-bold">{stats?.hotLeads ?? 0}</span>
                <span className="text-xs text-muted-foreground">Hot</span>
              </div>
              <div className="flex flex-col items-center p-4 bg-muted/40 rounded-lg">
                <Thermometer className="h-6 w-6 text-yellow-500 mb-2" />
                <span className="text-2xl font-bold">{stats?.warmLeads ?? 0}</span>
                <span className="text-xs text-muted-foreground">Warm</span>
              </div>
              <div className="flex flex-col items-center p-4 bg-muted/40 rounded-lg">
                <Snowflake className="h-6 w-6 text-blue-400 mb-2" />
                <span className="text-2xl font-bold">{stats?.coldLeads ?? 0}</span>
                <span className="text-xs text-muted-foreground">Cold</span>
              </div>
            </div>
          </CardContent>
        </Card>
        <Card className="col-span-3">
          <CardHeader><CardTitle>Recent Activity</CardTitle></CardHeader>
          <CardContent>
            <div className="space-y-4">
              {stats?.recentLeads && stats.recentLeads.length > 0 ? (
                stats.recentLeads.slice(0, 5).map((lead) => (
                  <div key={lead.id} className="flex items-center gap-4">
                    <div className="flex h-9 w-9 items-center justify-center rounded-full bg-muted">
                      <MapPin className="h-4 w-4 text-muted-foreground" />
                    </div>
                    <div className="flex flex-col gap-0.5 flex-1 min-w-0">
                      <p className="text-sm font-medium leading-none truncate">{lead.business_name}</p>
                      <p className="text-xs text-muted-foreground truncate">{lead.category || "Uncategorized"} • {lead.address || "No address"}</p>
                    </div>
                    <div className="text-xs text-muted-foreground whitespace-nowrap">
                      {lead.created_at ? formatTimeAgo(lead.created_at) : "—"}
                    </div>
                  </div>
                ))
              ) : (
                <div className="flex flex-col items-center justify-center py-8 text-muted-foreground">
                  <TrendingUp className="h-8 w-8 opacity-20 mb-2" />
                  <p className="text-sm">No activity yet</p>
                  <p className="text-xs">Start scraping to see leads here</p>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { Badge } from "@/components/ui/badge";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Loader2, Phone, Star, Flame, Thermometer, Snowflake, GripVertical } from "lucide-react";
import LeadDetailModal from "@/components/leads/LeadDetailModal";
import { api } from "@/lib/api";
import type { Lead } from "@geolead/types";

const PIPELINE_COLUMNS = [
    { id: "new", label: "New", color: "bg-blue-500", description: "Freshly scraped" },
    { id: "contacted", label: "Contacted", color: "bg-yellow-500", description: "Initial outreach" },
    { id: "follow_up", label: "Follow Up", color: "bg-purple-500", description: "Needs follow up" },
    { id: "qualified", label: "Qualified", color: "bg-green-500", description: "Good fit" },
    { id: "negotiating", label: "Negotiating", color: "bg-indigo-500", description: "In talks" },
    { id: "won", label: "Won ✓", color: "bg-emerald-500", description: "Deal closed" },
    { id: "lost", label: "Lost", color: "bg-red-500", description: "Not interested" },
];

const ScoreIcon = ({ score }: { score: string | null }) => {
    if (score === "hot") return <Flame className="h-3 w-3 text-orange-500" />;
    if (score === "warm") return <Thermometer className="h-3 w-3 text-yellow-600" />;
    if (score === "cold") return <Snowflake className="h-3 w-3 text-blue-500" />;
    return null;
};

export default function PipelinePage() {
    const [leads, setLeads] = useState<Lead[]>([]);
    const [loading, setLoading] = useState(true);
    const [selectedLead, setSelectedLead] = useState<Lead | null>(null);
    const [draggingId, setDraggingId] = useState<string | null>(null);

    const fetchLeads = async () => {
        setLoading(true);
        try {
            // Fetch all non-paginated leads for pipeline
            const result = await api.getLeads({ pageSize: "500" });
            if (result.success) setLeads(result.data);
        } catch (err) { console.error(err); }
        finally { setLoading(false); }
    };

    useEffect(() => { fetchLeads(); }, []);

    const getColumnLeads = (status: string) => leads.filter(l => l.lead_status === status);

    const handleDrop = async (e: React.DragEvent, targetStatus: string) => {
        e.preventDefault();
        const leadId = e.dataTransfer.getData("leadId");
        if (!leadId) return;

        // Optimistic update
        setLeads(prev => prev.map(l => l.id === leadId ? { ...l, lead_status: targetStatus } : l));
        setDraggingId(null);

        try {
            await api.updateLead(leadId, { lead_status: targetStatus });
        } catch (err) {
            console.error("Status update failed:", err);
            fetchLeads(); // Rollback on error
        }
    };

    if (loading) return (
        <div className="flex items-center justify-center h-[60vh] text-muted-foreground">
            <Loader2 className="h-6 w-6 animate-spin mr-2" />Loading pipeline...
        </div>
    );

    return (
        <div className="flex flex-col gap-4 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Pipeline</h1>
                    <p className="text-muted-foreground">Drag leads between stages to manage your workflow.</p>
                </div>
                <Button variant="outline" size="sm" onClick={fetchLeads}><Loader2 className="h-3 w-3 mr-1" />Refresh</Button>
            </div>

            <div className="flex gap-3 overflow-x-auto pb-4" style={{ minHeight: "70vh" }}>
                {PIPELINE_COLUMNS.map((col) => {
                    const columnLeads = getColumnLeads(col.id);
                    return (
                        <div
                            key={col.id}
                            className="flex-shrink-0 w-64 flex flex-col"
                            onDragOver={(e) => e.preventDefault()}
                            onDrop={(e) => handleDrop(e, col.id)}
                        >
                            {/* Column Header */}
                            <div className="flex items-center gap-2 mb-3 px-1">
                                <div className={`h-2.5 w-2.5 rounded-full ${col.color}`} />
                                <h3 className="text-sm font-semibold flex-1">{col.label}</h3>
                                <Badge variant="secondary" className="text-xs">{columnLeads.length}</Badge>
                            </div>

                            {/* Cards Container */}
                            <div className="flex-1 space-y-2 bg-muted/30 rounded-lg p-2 min-h-[200px]">
                                {columnLeads.length === 0 && (
                                    <p className="text-xs text-muted-foreground text-center pt-8">{col.description}</p>
                                )}
                                {columnLeads.map((lead) => (
                                    <div
                                        key={lead.id}
                                        draggable
                                        onDragStart={(e) => {
                                            e.dataTransfer.setData("leadId", lead.id);
                                            setDraggingId(lead.id);
                                        }}
                                        onDragEnd={() => setDraggingId(null)}
                                        onClick={() => setSelectedLead(lead)}
                                        className={`bg-background rounded-md p-3 shadow-sm border cursor-pointer transition-all
                                            hover:shadow-md hover:border-primary/30
                                            ${draggingId === lead.id ? "opacity-50 rotate-2" : ""}`}
                                    >
                                        <div className="flex items-start gap-2">
                                            <GripVertical className="h-4 w-4 text-muted-foreground/40 mt-0.5 shrink-0 cursor-grab" />
                                            <div className="flex-1 min-w-0">
                                                <p className="text-sm font-medium truncate">{lead.business_name}</p>
                                                {lead.category && <p className="text-xs text-muted-foreground truncate">{lead.category}</p>}
                                                <div className="flex items-center gap-2 mt-1.5">
                                                    <ScoreIcon score={lead.lead_score} />
                                                    {lead.google_rating && (
                                                        <span className="flex items-center gap-0.5 text-xs">
                                                            <Star className="h-2.5 w-2.5 text-yellow-500 fill-yellow-500" />{lead.google_rating}
                                                        </span>
                                                    )}
                                                    {lead.phone_number && <Phone className="h-2.5 w-2.5 text-green-600" />}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>

            {selectedLead && (
                <LeadDetailModal lead={selectedLead} onClose={() => setSelectedLead(null)}
                    onUpdate={(updated) => { setLeads(leads.map(l => l.id === updated.id ? updated : l)); setSelectedLead(updated); }} />
            )}
        </div>
    );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { cn } from "@/lib/utils";
import {
